-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial misstatements threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Electronics Inc., the engagement team sets overall materiality at $200,000. The team identifies a $350 misclassification between office supplies and postage expense. Under AU-C 450, the auditor should treat this misstatement as:', '["Clearly trivial and not required to be accumulated", "An uncorrected misstatement that must be communicated to management", "A projected misstatement requiring further sampling", "A significant deficiency reportable to those charged with governance"]'::jsonb, 0, 'Under AU-C 450.A2, misstatements below a clearly trivial threshold are inconsequential both individually and in aggregate and need not be accumulated. A $350 error against $200,000 materiality (0.18%) falls well below any reasonable threshold. While choice B describes the treatment for misstatements above clearly trivial, AU-C 450 distinguishes between trivial amounts and those requiring accumulation.', 'medium', 2),

-- Q2: medium / L2 — Summary of uncorrected misstatements in representation letter
(1, 'Misstatements and Control Deficiencies', 'While completing the audit of Haverford Building Supply LLC, the auditor accumulated $18,000 in uncorrected misstatements against overall materiality of $75,000. Management declines to adjust three of the identified items. Under AU-C 450, the auditor should:', '["Issue a qualified opinion because uncorrected misstatements exceed 20% of materiality", "Request a written representation from management acknowledging the uncorrected misstatements and asserting they are immaterial", "Reduce the materiality level to $18,000 and expand testing", "Withdraw from the engagement if management refuses to correct identified misstatements"]'::jsonb, 1, 'Under AU-C 450.14, the auditor must request a written representation from management that it believes the effects of uncorrected misstatements are immaterial, both individually and in aggregate. The representation letter should include or attach a summary of these items. Choice A is incorrect because the 20% threshold is not a defined standard; rather, the auditor evaluates qualitative and quantitative factors.', 'medium', 2),

-- Q3: easy / L1 — Fraud vs error distinction in misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what distinguishes a misstatement arising from fraud from one arising from error?', '["Fraud-related misstatements always exceed materiality, while errors may be immaterial", "Fraud-related misstatements require immediate withdrawal from the engagement", "Fraud involves intentional action, while error involves unintentional mistakes", "Error-related misstatements are reported only to management, while fraud is reported to regulators"]'::jsonb, 2, 'Under AU-C 240.02 and AU-C 450, the distinguishing factor between fraud and error is intent. Fraud involves intentional acts, including fraudulent financial reporting or misappropriation of assets. Errors are unintentional misstatements or omissions. Choice A is incorrect because fraud can result in immaterial amounts, and the auditor must still evaluate fraud risk regardless of the misstatement size.', 'easy', 1),

-- Q4: hard / L4 — Iron curtain vs rollover approach evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakewood Energy Partners, the auditor identifies $30,000 in current-year misstatements and notes $45,000 in uncorrected prior-year misstatements that continue to affect the current-year balance sheet. Overall materiality is $60,000. Under the rollover approach, current-year misstatements alone are immaterial, but the iron curtain approach shows a $75,000 cumulative balance sheet effect. The auditor should:', '["Accept the rollover result since the current-year misstatements are below materiality", "Average the two approaches and evaluate whether $52,500 exceeds materiality", "Issue a qualified opinion based solely on the iron curtain approach result", "Consider both approaches and exercise professional judgment, recognizing that the cumulative balance sheet impact may require further evaluation"]'::jsonb, 3, 'Under AU-C 450.A16, the auditor should consider both the rollover approach (current-year originating misstatements) and the iron curtain approach (cumulative balance sheet effect) when evaluating uncorrected misstatements. Neither approach alone is sufficient. Choice A is incorrect because ignoring the cumulative effect understates the risk; AU-C 450 requires the auditor to evaluate the aggregate effect on the financial statements as a whole.', 'hard', 4),

-- Q5: hard / L4 — Qualitative factors overriding quantitative immateriality
(1, 'Misstatements and Control Deficiencies', 'Atlas Pharmaceuticals Inc. reports net income of $5 million and the auditor sets materiality at $250,000. The auditor discovers a $45,000 misstatement involving improper capitalization of executive travel expenses. Although quantitatively immaterial, management intentionally misclassified the expenses. Under AU-C 450 and AU-C 240, the auditor should:', '["Evaluate the qualitative significance of the intentional misstatement, as it may indicate a risk of material misstatement due to fraud regardless of the dollar amount", "Accumulate the misstatement on the summary of uncorrected items and proceed without further action", "Issue an adverse opinion because any intentional misstatement constitutes fraud", "Require management to restate prior-period financial statements before issuing an opinion"]'::jsonb, 0, 'Under AU-C 450.A4, the auditor must consider qualitative factors, including whether a misstatement results from intentional action. AU-C 240.35 requires the auditor to evaluate whether an intentional misstatement, even if immaterial, indicates fraud risk that could have broader implications. Choice B is incorrect because simply accumulating the misstatement without evaluating the fraud implications ignores the auditor''s responsibility under AU-C 240.', 'hard', 4),

-- Q6: medium / L3 — Deficiency in design vs deficiency in operation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Belmont Retail Group, the auditor notes that the company designed an effective three-way match control for accounts payable but discovered that clerks routinely bypass the matching requirement for invoices under $500. Under AU-C 265, this situation represents:', '["A deficiency in the design of the control, because the threshold is set too high", "A deficiency in the operation of the control, because the control exists but is not functioning as designed", "Neither a design nor operating deficiency, because the bypassed amounts are immaterial", "A material weakness, because any deviation from a designed control is automatically material"]'::jsonb, 1, 'Under AU-C 265.A1, a deficiency in operation exists when a properly designed control does not operate as designed or the person performing the control lacks the competence or authority to do so effectively. The three-way match was designed correctly but is not being followed. Choice A is incorrect because the design of the control itself is sound; the failure is in its execution by personnel who bypass it.', 'medium', 3),

-- Q7: medium / L2 — Tolerable misstatement in sampling
(1, 'Misstatements and Control Deficiencies', 'Brookstone & Associates is auditing Cedar Valley Foods and uses audit sampling to test revenue transactions. The auditor sets tolerable misstatement at $40,000 and finds $12,000 in actual misstatements in the sample. After projecting to the population, the estimated misstatement is $38,000. Under AU-C 530, the auditor should conclude that:', '["The account is materially misstated because actual misstatements were found in the sample", "Additional testing is unnecessary because the projected misstatement is below tolerable misstatement", "The projected misstatement is close to tolerable misstatement, requiring the auditor to evaluate the risk that actual misstatement exceeds tolerable misstatement", "Tolerable misstatement should be increased to $50,000 to accommodate the projected amount"]'::jsonb, 2, 'Under AU-C 530.A23, when the projected misstatement approaches tolerable misstatement, the auditor recognizes a higher risk that actual misstatement could exceed the tolerable amount, even though the point estimate is below it. The auditor should consider performing additional procedures or evaluating other evidence. Choice B is incorrect because proximity to the tolerable threshold warrants further consideration rather than automatic acceptance.', 'medium', 2),

-- Q8: medium / L3 — Prior-period uncorrected misstatements effect on current period
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Peak Construction Co., the auditor notes that $22,000 in uncorrected misstatements from the prior year affect the opening balances of accounts payable and retained earnings. Current-year materiality is $50,000, and no new misstatements have been identified. Under AU-C 450, the effect of prior-period uncorrected misstatements on the current period is most accurately described as:', '["Irrelevant, because prior-period misstatements are the responsibility of the predecessor auditor", "Automatically requiring a qualified opinion on the current-period financial statements", "Limited to the income statement, since balance sheet accounts self-correct over time", "Requiring evaluation for their effect on the current-period financial statements, including whether they cause a material misstatement in the current period"]'::jsonb, 3, 'Under AU-C 450.10, the auditor must include in the aggregate of uncorrected misstatements the effect of prior-period uncorrected misstatements on current-period balances. Even if no new misstatements arise, carryforward effects on the balance sheet or income statement may be material. Choice C is incorrect because not all misstatements self-correct, and balance sheet effects may persist indefinitely until adjusted.', 'medium', 3),

-- Q9: easy / L1 — Two conditions for a control deficiency to exist
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when which condition is present?', '["A control is missing or ineffective, creating a reasonable possibility that a misstatement could occur and not be prevented or detected on a timely basis", "The entity has no internal audit department and management does not review reconciliations", "A control fails during testing and the auditor issues a qualified opinion", "The entity lacks a written code of ethics and has not designated a compliance officer"]'::jsonb, 0, 'Under AU-C 265.07, a deficiency in internal control exists when the design or operation of a control does not allow management or employees to prevent or detect and correct misstatements on a timely basis. The definition requires both a control gap in design or operation and a possibility of undetected misstatement. Choice B is incorrect because those specific conditions may or may not constitute deficiencies depending on the entity''s circumstances and do not define the general standard.', 'easy', 1),

-- Q10: hard / L3 — Entity-level control deficiency with pervasive implications
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Northwest Timber Corp., the auditor discovers that the CFO has overridden month-end journal entry review controls on multiple occasions over the past 18 months to adjust revenue and inventory accounts. The individual misstatements are each below performance materiality. Under AU-C 265 and AU-C 240, the auditor should analyze this pattern as:', '["A series of isolated control deviations that individually do not warrant escalation", "An entity-level control deficiency with pervasive implications, because management override of controls indicates a tone-at-the-top issue affecting multiple financial statement assertions", "A significant deficiency limited to the revenue and inventory accounts that does not affect the overall control environment", "A compensating control failure that can be mitigated by increasing substantive testing in the affected accounts"]'::jsonb, 1, 'Under AU-C 265.A14, control deficiencies related to the control environment, such as management override, are evaluated as entity-level deficiencies with potentially pervasive effects. AU-C 240.31 identifies management override as a presumed fraud risk. Choice A is incorrect because a pattern of override by a senior executive represents a systemic weakness in the control environment, not isolated deviations, regardless of individual amounts.', 'hard', 3),

-- Q11: medium / L2 — Performance materiality and its purpose
(1, 'Misstatements and Control Deficiencies', 'The audit of Silverline Technologies Inc. sets overall materiality at $100,000. The engagement partner establishes performance materiality at $65,000 to reduce the probability that aggregate uncorrected and undetected misstatements exceed overall materiality. Under AU-C 320, performance materiality is set below overall materiality primarily because:', '["Regulators require a fixed percentage reduction from overall materiality", "It accounts for the risk that management will not correct identified misstatements", "It provides a margin for undetected misstatements beyond those the auditor identifies during testing", "It represents the threshold for communicating deficiencies to those charged with governance"]'::jsonb, 2, 'Under AU-C 320.A12, performance materiality is set at an amount less than overall materiality to reduce the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality for the financial statements as a whole. This margin accounts for misstatements the auditor cannot detect. Choice B is incorrect because the purpose is not about management''s willingness to correct but about the inherent limitation of sampling and testing procedures.', 'medium', 2),

-- Q12: medium / L3 — Impact of misstatement on debt covenant compliance
(1, 'Misstatements and Control Deficiencies', 'Ridgeview Manufacturing LLC has a debt covenant requiring a current ratio of at least 1.5:1. Before considering uncorrected misstatements, the company reports a current ratio of 1.55:1. The auditor identifies $90,000 in uncorrected misstatements that would reclassify current assets to noncurrent assets. Overall materiality is $300,000. Under AU-C 450, the auditor should evaluate this misstatement by considering:', '["Only quantitative materiality, since the misstatement is below the $300,000 threshold", "Whether the misstatement affects the income statement, since covenant ratios are secondary", "Whether prior-period misstatements also affected the covenant ratio", "The qualitative significance of the misstatement, because it could cause the entity to violate the debt covenant even though the amount is below materiality"]'::jsonb, 3, 'Under AU-C 450.A4, the auditor evaluates misstatements considering both quantitative and qualitative factors, including whether a misstatement could affect compliance with debt covenants or contractual obligations. A covenant breach can trigger loan acceleration regardless of the dollar amount. Choice A is incorrect because limiting the evaluation to quantitative materiality alone ignores the potentially severe consequence of covenant violation.', 'medium', 3),

-- Q13: easy / L1 — Timing of written deficiency communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, when must the auditor communicate significant deficiencies and material weaknesses in writing to those charged with governance?', '["No later than 60 days following the report release date", "Immediately upon discovery during fieldwork", "Within 30 days after the fiscal year-end", "At the planning stage of the subsequent audit engagement"]'::jsonb, 0, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This timeline allows the auditor to fully evaluate all identified deficiencies before formal communication. Choice B is incorrect because while the auditor may communicate orally during fieldwork, the formal written communication deadline is tied to the report release date.', 'easy', 1),

-- Q14: easy / L1 — Accumulation of misstatements requirement
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which misstatements must the auditor accumulate during the audit?', '["Only misstatements that individually exceed performance materiality", "All misstatements identified during the audit except those that are clearly trivial", "Only misstatements that management agrees are errors", "Only misstatements discovered through substantive analytical procedures"]'::jsonb, 1, 'Under AU-C 450.05, the auditor is required to accumulate all misstatements identified during the audit, other than those that are clearly trivial. This includes factual, judgmental, and projected misstatements regardless of their source or whether management acknowledges them. Choice A is incorrect because the accumulation threshold is clearly trivial, not performance materiality; many misstatements below performance materiality must still be accumulated.', 'easy', 1),

-- Q15: hard / L4 — Evaluate whether to modify opinion for near-materiality misstatements
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Aerospace Corp. has $85,000 in aggregate uncorrected misstatements against overall materiality of $90,000. Management refuses to adjust the financial statements, asserting the amounts are reasonable estimates. The misstatements affect inventory valuation, accounts receivable aging, and warranty accruals across multiple assertions. The auditor should:', '["Issue an unmodified opinion because the aggregate misstatements are technically below materiality", "Issue a qualified opinion because any uncorrected misstatement above 90% of materiality requires modification", "Evaluate whether the proximity to materiality, combined with the risk of undetected misstatements and the pervasive nature across multiple assertions, warrants an opinion modification", "Withdraw from the engagement because management''s refusal to adjust demonstrates a lack of integrity"]'::jsonb, 2, 'Under AU-C 450.11, the auditor must evaluate whether uncorrected misstatements are material individually or in aggregate, considering both the size and nature of the misstatements and their effect on particular classes of transactions, balances, and disclosures. When aggregated misstatements approach materiality and span multiple assertions, the risk of total misstatement exceeding materiality increases. Choice A is incorrect because a narrow margin below materiality does not automatically result in an unmodified opinion when undetected misstatements likely exist.', 'hard', 4),

-- Q16: medium / L3 — Recurring misstatements indicating systemic control weakness
(1, 'Misstatements and Control Deficiencies', 'During three consecutive audits of Mapleview Hospitality Group, the auditor identifies similar accounts payable cutoff misstatements ranging from $15,000 to $25,000 each year. Management corrects the misstatements each year but does not implement process changes. Under AU-C 265, the auditor should analyze this pattern as:', '["Acceptable, because management corrects the misstatements each year", "An inherent limitation of the accounts payable process that cannot be eliminated", "A minor control deviation that requires only a management letter comment", "Evidence of a control deficiency that may rise to a significant deficiency or material weakness, because the recurring nature suggests the underlying control is ineffective"]'::jsonb, 3, 'Under AU-C 265.A7, the auditor considers the recurrence of a deficiency when evaluating its severity. A control that repeatedly fails to prevent misstatements, even when corrected by management after the fact, indicates an ongoing design or operating deficiency. Choice A is incorrect because management''s willingness to correct misstatements after detection does not address the root cause or reduce the severity of the underlying control weakness.', 'medium', 3),

-- Q17: easy / L1 — Three categories of misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what are the three categories of misstatements that an auditor may identify?', '["Factual misstatements, judgmental misstatements, and projected misstatements", "Material misstatements, immaterial misstatements, and trivial misstatements", "Intentional misstatements, unintentional misstatements, and systemic misstatements", "Quantitative misstatements, qualitative misstatements, and disclosure misstatements"]'::jsonb, 0, 'Under AU-C 450.A3, misstatements are classified as factual (determined with certainty), judgmental (arising from management''s estimates or judgments the auditor considers unreasonable), and projected (the auditor''s best estimate of misstatements in populations based on sample results). Choice B is incorrect because material, immaterial, and trivial describe the significance of misstatements, not their nature or source.', 'easy', 1),

-- Q18: medium / L3 — Offsetting misstatements in different accounts
(1, 'Misstatements and Control Deficiencies', 'During the audit of Coastal Dynamics LLC, the auditor identifies a $40,000 overstatement of revenue and a $35,000 understatement of expenses, both in the same reporting period. Overall materiality is $60,000. Under AU-C 450, the auditor should analyze the effect of these misstatements by considering:', '["Only the net effect of $5,000, since opposing misstatements offset each other", "Both the individual and aggregate effects, recognizing that offsetting misstatements in different accounts may mask the true impact on individual financial statement line items", "Only the revenue misstatement, since it is the larger of the two amounts", "Whether the misstatements originated from the same transaction cycle"]'::jsonb, 1, 'Under AU-C 450.A18, the auditor should not allow misstatements to be offset against each other without considering their individual effects on specific financial statement line items and classes of transactions. Netting a revenue overstatement against an expense understatement obscures the impact on each line item. Choice A is incorrect because offsetting misstatements from different accounts can mask material errors in individual balances even when the net effect appears small.', 'medium', 3),

-- Q19: medium / L2 — Segregation of duties control deficiency classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Summit Valley Credit Union, the auditor discovers that the same employee who processes wire transfers also reconciles the bank statement each month with no independent review. The credit union processes approximately $8 million in wire transfers annually. Under AU-C 265, the auditor should classify this situation as:', '["An immaterial finding because credit unions have limited staff available", "A deficiency in operation only, since the entity has a reconciliation process in place", "At minimum a significant deficiency, because the lack of segregation of duties in a high-volume process creates a reasonable possibility of material misstatement", "A compliance finding reportable only to the regulatory agency"]'::jsonb, 2, 'Under AU-C 265.A8, the auditor evaluates the magnitude of potential misstatement and the volume of activity processed by the deficient control. A single employee controlling both wire transfer initiation and bank reconciliation for $8 million in annual transactions creates a reasonable possibility of undetected misstatement. Choice B is incorrect because the deficiency is in control design, not merely operation, since no independent oversight exists over the combined functions.', 'medium', 2),

-- Q20: medium / L2 — Documentation requirements for accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork at Westbrook Chemical Corp., the auditor accumulated $28,000 in uncorrected misstatements, all of which management believes are immaterial. Overall materiality is $150,000. Under AU-C 450, the auditor''s workpapers should include:', '["Only misstatements that were corrected during the audit", "A summary limited to misstatements above performance materiality", "Documentation of uncorrected misstatements only if they exceed 50% of materiality", "A listing of all accumulated uncorrected misstatements, the auditor''s conclusion about whether they are material, and management''s reasons for not correcting them"]'::jsonb, 3, 'Under AU-C 450.15, the auditor must document the amount below which misstatements are regarded as clearly trivial, all misstatements accumulated during the audit, and the auditor''s conclusion about whether uncorrected misstatements are material individually or in aggregate. Choice A is incorrect because the documentation requirement explicitly covers uncorrected misstatements, not only those that were corrected.', 'medium', 2),

-- Q21: easy / L1 — Communication of deficiencies below significant level
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is the auditor''s responsibility for control deficiencies that are neither significant deficiencies nor material weaknesses?', '["The auditor may communicate them to management but is not required to do so in writing", "The auditor must communicate all control deficiencies in writing to those charged with governance", "The auditor has no responsibility to communicate deficiencies below the significant deficiency level", "The auditor must include all deficiencies in the audit report"]'::jsonb, 0, 'Under AU-C 265.12, the auditor should communicate to management control deficiencies identified during the audit that are of sufficient importance to merit management''s attention but do not rise to the level of significant deficiency or material weakness. This communication may be oral or written. Choice C is incorrect because AU-C 265 does establish a responsibility to communicate other deficiencies to management when they merit attention.', 'easy', 1),

-- Q22: easy / L2 — Misclassification as a misstatement
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ferndale Organic Markets, the auditor finds that $12,000 in repair and maintenance costs were capitalized as equipment on the balance sheet. Under AU-C 450, this misclassification is treated as:', '["A disclosure deficiency that requires only a footnote adjustment", "A misstatement because it causes both the balance sheet and income statement to be misstated", "An acceptable alternative accounting treatment within management''s discretion", "A presentation issue that does not affect the financial statements"]'::jsonb, 1, 'Under AU-C 450.04, a misstatement is defined as a difference between the amount, classification, presentation, or disclosure of a reported financial statement item and what is required under the applicable financial reporting framework. Capitalizing expenses misstates both total assets and net income. Choice D is incorrect because misclassification between expense and asset accounts directly affects the financial statements'' accuracy, not merely their presentation.', 'easy', 2),

-- Q23: medium / L3 — Qualitative impact of misstatements on trend analysis
(1, 'Misstatements and Control Deficiencies', 'The auditor of Cascade Financial Advisors LLC identifies $55,000 in uncorrected revenue misstatements over two consecutive years. Total revenue averages $2 million annually. While the dollar amounts are below materiality of $80,000, the misstatements consistently inflate the revenue growth rate reported to investors. Under AU-C 450, the auditor should analyze this by:', '["Accepting the misstatements because they are individually below materiality in each year", "Evaluating only the current-year misstatement in isolation from prior periods", "Considering the qualitative impact on financial statement trends and user decision-making, even when amounts are quantitatively immaterial", "Requiring management to correct only the current-year amount"]'::jsonb, 2, 'Under AU-C 450.A4, the auditor considers qualitative factors including whether a misstatement affects trends, ratios, or other measures used by financial statement users. Consistently inflating revenue growth affects users'' assessment of the entity''s trajectory and comparability. Choice A is incorrect because quantitative immateriality does not override qualitative concerns when misstatements distort meaningful trends relied upon by investors.', 'medium', 3),

-- Q24: medium / L3 — IT general control deficiency cascading to application controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Quantum Data Solutions Inc., the auditor identifies a deficiency in access controls for the enterprise resource planning system: terminated employees retained active user accounts for an average of 45 days after departure. Eight application controls depend on these access restrictions to function properly. Under AU-C 265, the auditor should evaluate this deficiency by considering:', '["Only the access control deficiency in isolation, since it is a single control", "The deficiency as immaterial because no actual unauthorized transactions were detected", "Only whether compensating controls fully mitigate the access control weakness", "The cascading effect on all dependent application controls, since an IT general control deficiency can undermine multiple automated controls simultaneously"]'::jsonb, 3, 'Under AU-C 265.A12, the auditor considers the relationship between IT general controls and application controls when evaluating severity. A weakness in user access management can render dependent application controls ineffective because unauthorized users may circumvent them. Choice B is incorrect because the evaluation focuses on the reasonable possibility of misstatement, not whether an actual misstatement occurred; the potential exposure across eight dependent controls heightens severity.', 'medium', 3),

-- Q25: hard / L4 — Evaluate classification of near-miss deficiency with compensating control
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redstone Capital Management Inc., the auditor discovers that the fund accounting reconciliation control failed to detect a $180,000 pricing error in a portfolio with $25 million in assets. A secondary review control detected the error before financial statements were issued. Materiality is $500,000. The senior argues for a control deficiency classification while the manager believes it is a significant deficiency. Under AU-C 265, the most appropriate evaluation is:', '["The failure of the primary control constitutes at least a significant deficiency because the magnitude of the undetected error indicates a reasonable possibility that a material misstatement could occur if the compensating control also failed", "The finding is only a control deficiency because the secondary review successfully prevented a misstatement in the financial statements", "The deficiency is a material weakness because any control failure involving $180,000 is automatically material", "No deficiency exists because the overall system of controls ultimately prevented the misstatement"]'::jsonb, 0, 'Under AU-C 265.A9, the auditor evaluates severity based on the magnitude of potential misstatement and the likelihood that the deficiency could result in a material misstatement, not whether a misstatement actually occurred. A compensating control reduces but does not eliminate the severity. Choice B is incorrect because AU-C 265 evaluates what could happen, not merely what did happen; reliance on a single compensating control leaves residual risk warranting at minimum a significant deficiency classification.', 'hard', 4),

-- Q26: hard / L4 — Systematic override and fraud risk interplay in deficiency classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northern Highlands Resort Group, the auditor discovers that the general manager routinely approves revenue adjustments exceeding the $10,000 threshold that requires controller sign-off. Over the past year, 23 adjustments totaling $175,000 bypassed the required dual-approval control. No fraud evidence has been found, but the override concentrates authorization power in one individual. Materiality is $200,000. Under AU-C 265 and AU-C 240, the auditor should recommend classifying this as:', '["A significant deficiency, since no actual misstatement resulted from the override pattern", "A material weakness, because the systematic override of a key control by a senior manager creates a reasonable possibility of material misstatement and elevates fraud risk", "A control deficiency, because the override amounts are individually below materiality", "An operational finding outside the scope of the financial statement audit"]'::jsonb, 1, 'Under AU-C 265.A14, indicators of material weakness include management override of controls and an ineffective control environment. AU-C 240.32 establishes that the risk of management override cannot be reduced to an acceptably low level through controls alone. Systematic bypassing of dual-approval controls by a senior manager represents both a control environment failure and elevated fraud risk. Choice A is incorrect because the classification depends on the reasonable possibility of misstatement, not whether actual misstatement occurred.', 'hard', 4),

-- Q27: medium / L2 — Clearly trivial vs immaterial distinction
(1, 'Misstatements and Control Deficiencies', 'The auditor of Bridgeport Mechanical Services LLC sets materiality at $120,000 and establishes a clearly trivial threshold of $2,400. During testing, the auditor identifies a $4,500 misstatement in prepaid insurance. Under AU-C 450, this misstatement should be:', '["Disregarded because it is immaterial to the financial statements", "Reported directly to those charged with governance as a significant deficiency", "Accumulated on the summary of uncorrected misstatements because it exceeds the clearly trivial threshold", "Projected to the full population of prepaid expense transactions"]'::jsonb, 2, 'Under AU-C 450.05, the auditor accumulates all identified misstatements unless they are clearly trivial, meaning amounts below a threshold that are inconsequential individually and in aggregate. A $4,500 misstatement exceeding the $2,400 clearly trivial threshold must be accumulated. Choice A is incorrect because immaterial and clearly trivial are distinct concepts; a misstatement can be immaterial individually yet still require accumulation for aggregate evaluation.', 'medium', 2),

-- Q28: medium / L2 — Related-party disclosure omission as misstatement
(1, 'Misstatements and Control Deficiencies', 'During the audit of Thornhill Properties Inc., the auditor discovers that the related-party transaction disclosures omit a $320,000 lease arrangement between the company and an entity controlled by the CEO. Total related-party transactions are $1.2 million. Materiality is $400,000. Under AU-C 450, the auditor should treat this omission as:', '["A management letter comment, since disclosure omissions are less significant than numerical errors", "Immaterial because the omitted lease is below overall materiality", "A supplemental finding to be communicated only in the subsequent audit", "A misstatement that must be accumulated and evaluated for its qualitative significance, because related-party disclosure omissions may be material regardless of dollar amount"]'::jsonb, 3, 'Under AU-C 450.A5, misstatements include omissions from financial statement disclosures needed to achieve fair presentation. Related-party disclosures under ASC 850 are qualitatively significant because they affect users'' understanding of transactions that may not be conducted at arm''s length. Choice A is incorrect because AU-C 450 treats disclosure misstatements with the same rigor as numerical misstatements, and related-party omissions carry heightened qualitative importance.', 'medium', 2),

-- Q29: easy / L1 — Material weakness vs significant deficiency distinction
(1, 'Misstatements and Control Deficiencies', 'What primarily distinguishes a material weakness from a significant deficiency under AU-C 265?', '["A material weakness involves a reasonable possibility that a material misstatement will not be prevented or detected, while a significant deficiency is less severe but still merits governance attention", "A material weakness requires actual financial loss, while a significant deficiency requires only a potential loss", "A material weakness must be reported to regulators, while a significant deficiency is reported only to management", "A material weakness applies only to public companies, while a significant deficiency applies to all entities"]'::jsonb, 0, 'Under AU-C 265.07, a material weakness is a deficiency, or combination of deficiencies, such that there is a reasonable possibility that a material misstatement will not be prevented or detected and corrected on a timely basis. A significant deficiency is less severe but sufficiently important to merit attention by those charged with governance. Choice B is incorrect because both classifications are based on the possibility of misstatement, not on whether actual losses occurred.', 'easy', 1),

-- Q30: easy / L1 — Auditor not required to search for all deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, is the auditor required to perform procedures specifically designed to identify all control deficiencies?', '["Yes, the auditor must design procedures to identify every control deficiency in the entity", "No, the auditor identifies control deficiencies as a byproduct of the audit and is not required to search for all deficiencies", "Yes, but only for entities with revenues exceeding $50 million", "No, because control deficiency identification is solely management''s responsibility"]'::jsonb, 1, 'Under AU-C 265.04, the audit is not specifically designed to identify all control deficiencies. The auditor may become aware of control deficiencies during the risk assessment process, testing of controls, or other audit procedures, but there is no requirement to search for all deficiencies. Choice D is incorrect because while management is responsible for maintaining effective controls, the auditor has a responsibility to communicate deficiencies identified during the audit.', 'easy', 1)
;

COMMIT;
